sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.searchText = "";
  c.activeFilter = "all";
  c.pageSize = 6;
  c.currentPage = 1;

  c.filters = [
    { label: "All resources", value: "all" },
    { label: "Textbooks", value: "book" },
    { label: "Laptops", value: "laptop" },
    { label: "Lab kits", value: "kit" },
    { label: "Other", value: "other" }
  ];

  c.resetPage = function() {
    c.currentPage = 1;
  };

  c.clearSearch = function() {
    c.searchText = "";
    c.currentPage = 1;
  };

  c.setFilter = function(value) {
    c.activeFilter = value;
    c.currentPage = 1;
  };

  c.filteredAssets = function() {
    var assets = c.data.assets || [];
    var term = (c.searchText || "").toLowerCase().trim();

    return assets.filter(function(asset) {
      var matchesType =
        c.activeFilter === "all" || asset.art === c.activeFilter;

      var searchable = [
        asset.name,
        asset.assetId,
        asset.type,
        asset.location
      ].join(" ").toLowerCase();

      return matchesType && (!term || searchable.indexOf(term) !== -1);
    });
  };

  c.countFor = function(filter) {
    var previous = c.activeFilter;
    c.activeFilter = filter;
    var count = c.filteredAssets().length;
    c.activeFilter = previous;
    return count;
  };

  c.pageAssets = function() {
    var assets = c.filteredAssets();
    var start = (c.currentPage - 1) * c.pageSize;
    return assets.slice(start, start + c.pageSize);
  };

  c.totalPages = function() {
    return Math.max(1, Math.ceil(c.filteredAssets().length / c.pageSize));
  };

  c.startRecord = function() {
    return c.filteredAssets().length
      ? (c.currentPage - 1) * c.pageSize + 1
      : 0;
  };

  c.endRecord = function() {
    return Math.min(
      c.currentPage * c.pageSize,
      c.filteredAssets().length
    );
  };

  c.previousPage = function() {
    if (c.currentPage > 1) c.currentPage--;
  };

  c.nextPage = function() {
    if (c.currentPage < c.totalPages()) c.currentPage++;
  };

  c.resetFilters = function() {
    c.searchText = "";
    c.activeFilter = "all";
    c.currentPage = 1;
  };
};

sp_widget.css:
/* CAMPUSOPS ASSET CATALOGUE */

.co-catalog {
  --ca-ink:#34264f;
  --ca-muted:#887d99;
  --ca-purple:#8062c9;
  --ca-border:#e9e1f3;
  width:100%;
  color:var(--ca-ink);
  font-family:Inter,"Segoe UI",Arial,sans-serif;
  font-size:13px;
  line-height:1.55;
}

.co-catalog * { box-sizing:border-box; }
.co-catalog a { text-decoration:none; }
.co-catalog button,
.co-catalog input { font:inherit; }
.co-catalog a:focus-visible,
.co-catalog button:focus-visible,
.co-catalog input:focus-visible {
  outline:2px solid #8062c9;
  outline-offset:3px;
}

/* LAYOUT AND SIDEBAR */

.co-catalog .ca-layout {
  display:grid;
  grid-template-columns:218px minmax(0,1fr);
  align-items:stretch;
  gap:25px;
  width:100%;
}

.co-catalog .ca-sidebar {
  display:flex;
  flex-direction:column;
  min-width:0;
  min-height:690px;
  padding:20px 13px;
  border:1px solid #e9e0f5;
  border-radius:19px;
  background:linear-gradient(180deg,#f8f4ff,#f3effb);
}

.co-catalog .ca-brand {
  display:flex;
  align-items:center;
  gap:10px;
  padding:4px 7px 24px;
  color:#382b54;
}

.co-catalog .ca-brand-mark {
  display:grid;
  place-items:center;
  width:37px;
  height:37px;
  flex-shrink:0;
  border-radius:11px;
  background:#8062c9;
  color:white;
  font-size:19px;
  font-weight:800;
}

.co-catalog .ca-brand b {
  display:block;
  font-size:14px;
  line-height:1.2;
}

.co-catalog .ca-brand small {
  display:block;
  margin-top:4px;
  color:#8b7e9e;
  font-size:9px;
  font-weight:500;
}

.co-catalog .ca-nav-label {
  padding:9px 10px;
  color:#a092b6;
  font-size:9px;
  font-weight:800;
  letter-spacing:1.1px;
}

.co-catalog .ca-nav-spaced { margin-top:18px; }

.co-catalog .ca-nav {
  display:flex;
  align-items:center;
  gap:11px;
  margin:2px 0;
  padding:11px 10px;
  border-radius:10px;
  color:#6e6382;
  font-size:11px;
  font-weight:600;
  transition:background .18s,color .18s;
}

.co-catalog .ca-nav > span {
  display:grid;
  place-items:center;
  width:21px;
  flex-shrink:0;
  color:#8d79b5;
  font-size:16px;
}

.co-catalog .ca-nav:hover {
  background:rgba(255,255,255,.8);
  color:#513a83;
}

.co-catalog .ca-nav-active {
  background:#e8defa;
  color:#6245a0;
  font-weight:750;
}

.co-catalog .ca-nav-active > span { color:#7354b4; }

.co-catalog .ca-sidebar-bottom {
  display:flex;
  flex-direction:column;
  gap:4px;
  margin-top:auto;
  padding:18px 8px 3px;
  border-top:1px solid #e4dbef;
}

.co-catalog .ca-sidebar-bottom b {
  color:#59446f;
  font-size:10px;
}

.co-catalog .ca-sidebar-bottom small {
  color:#9386a5;
  font-size:9px;
}

/* HEADER */

.co-catalog .ca-main { min-width:0; }

.co-catalog .ca-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin:4px 0 23px;
}

.co-catalog .ca-eyebrow {
  color:#927bb7;
  font-size:9px;
  font-weight:800;
  letter-spacing:1.2px;
}

.co-catalog .ca-header h1 {
  margin:9px 0 5px;
  color:#34264f;
  font-size:clamp(25px,2.6vw,33px);
  font-weight:800;
  letter-spacing:-.8px;
  line-height:1.25;
}

.co-catalog .ca-header p {
  margin:0;
  color:#897d99;
  font-size:11px;
}

.co-catalog .ca-my-rentals {
  flex-shrink:0;
  padding:9px 12px;
  border:1px solid #e8def4;
  border-radius:10px;
  background:white;
  color:#7356ad;
  font-size:10px;
  font-weight:750;
}

/* SEARCH */

.co-catalog .ca-search-panel {
  margin-bottom:24px;
  padding:16px;
  border:1px solid var(--ca-border);
  border-radius:14px;
  background:rgba(255,255,255,.84);
}

.co-catalog .ca-search-panel label {
  display:block;
  margin-bottom:9px;
  color:#49385f;
  font-size:11px;
  font-weight:750;
}

.co-catalog .ca-search-row {
  display:flex;
  align-items:center;
  gap:10px;
  min-width:0;
  padding:0 12px;
  border:1px solid #e4d9f2;
  border-radius:10px;
  background:#fcfaff;
}

.co-catalog .ca-search-row:focus-within {
  border-color:#b6a1e1;
  box-shadow:0 0 0 3px rgba(128,98,201,.08);
}

.co-catalog .ca-search-symbol {
  color:#8062c9;
  font-size:21px;
}

.co-catalog .ca-search-row input {
  width:100%;
  min-width:0;
  height:42px;
  padding:0;
  border:0;
  outline:none;
  background:transparent;
  color:#44345d;
  font-size:11px;
  box-shadow:none;
}

.co-catalog .ca-search-row input:focus {
  outline:none;
  box-shadow:none;
}

.co-catalog .ca-search-row input::placeholder {
  color:#a297b2;
}

.co-catalog .ca-search-row button {
  padding:5px 8px;
  border:0;
  background:transparent;
  color:#7959b8;
  font-size:10px;
  cursor:pointer;
}

.co-catalog .ca-search-hint {
  margin-top:9px;
  color:#92869f;
  font-size:10px;
}

/* FILTERS AND SECTION HEADINGS */

.co-catalog .ca-catalogue { margin-bottom:24px; }

.co-catalog .ca-section-heading { margin-bottom:13px; }

.co-catalog .ca-section-heading h2 {
  margin:0;
  color:#403254;
  font-size:15px;
  font-weight:800;
}

.co-catalog .ca-section-heading p {
  margin:4px 0 0;
  color:#8c809b;
  font-size:10px;
}

.co-catalog .ca-filters {
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin-bottom:15px;
}

.co-catalog .ca-filters button {
  display:inline-flex;
  align-items:center;
  gap:7px;
  padding:7px 10px;
  border:1px solid #e9e1f3;
  border-radius:9px;
  background:white;
  color:#776a8b;
  font-size:10px;
  cursor:pointer;
  transition:background .15s,border-color .15s;
}

.co-catalog .ca-filters button span {
  color:#9a8eaa;
  font-size:9px;
}

.co-catalog .ca-filters button:hover {
  border-color:#cfc0eb;
  background:#faf7ff;
}

.co-catalog .ca-filters button.ca-filter-active {
  border-color:#8062c9;
  background:#8062c9;
  color:white;
}

.co-catalog .ca-filters button.ca-filter-active span {
  color:#eee5ff;
}

/* RESOURCE CARDS */

.co-catalog .ca-grid {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:12px;
}

.co-catalog .ca-card {
  display:flex;
  flex-direction:column;
  min-width:0;
  padding:15px;
  border:1px solid #e7def4;
  border-radius:14px;
  background:rgba(255,255,255,.88);
  box-shadow:0 4px 13px rgba(79,60,118,.025);
  transition:transform .18s,border-color .18s,box-shadow .18s;
}

.co-catalog .ca-card:hover {
  transform:translateY(-2px);
  border-color:#d4c4ee;
  box-shadow:0 8px 20px rgba(79,60,118,.07);
}

.co-catalog .ca-card-top {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-bottom:13px;
}

.co-catalog .ca-asset-symbol {
  display:grid;
  place-items:center;
  width:36px;
  height:36px;
  flex-shrink:0;
  border-radius:10px;
  background:#eee7fc;
  color:#7859b7;
  font-size:18px;
}

.co-catalog .ca-symbol-book {
  background:#eee7fc;
  color:#7859b7;
}

.co-catalog .ca-symbol-laptop {
  background:#e9f2ff;
  color:#547eaf;
}

.co-catalog .ca-symbol-kit {
  background:#fff0e3;
  color:#bd8248;
}

.co-catalog .ca-symbol-other {
  background:#e8f7f1;
  color:#519b82;
}

.co-catalog .ca-available {
  display:inline-flex;
  align-items:center;
  gap:5px;
  padding:4px 8px;
  border-radius:20px;
  background:#eaf7ef;
  color:#4c956f;
  font-size:9px;
  font-weight:750;
  white-space:nowrap;
}

.co-catalog .ca-available > span {
  width:5px;
  height:5px;
  border-radius:50%;
  background:#56a77b;
}

.co-catalog .ca-asset-type {
  margin-bottom:3px;
  color:#9588a6;
  font-size:9px;
  text-transform:uppercase;
  letter-spacing:.5px;
}

.co-catalog .ca-card h3 {
  margin:0;
  color:#44345d;
  font-size:13px;
  font-weight:800;
  overflow-wrap:anywhere;
}

.co-catalog .ca-asset-id {
  margin-top:5px;
  color:#9a8eaa;
  font-size:9px;
}

.co-catalog .ca-location {
  display:flex;
  flex-direction:column;
  gap:3px;
  margin-top:14px;
  padding:10px 0;
  border-top:1px solid #f0ebf6;
}

.co-catalog .ca-location span {
  color:#9589a5;
  font-size:9px;
}

.co-catalog .ca-location strong {
  color:#665776;
  font-size:10px;
  font-weight:650;
  overflow-wrap:anywhere;
}

.co-catalog .ca-details-link {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-top:auto;
  padding:10px 11px;
  border:1px solid #8062c9;
  border-radius:8px;
  background:#8062c9;
  color:white;
  font-size:10px;
  font-weight:750;
  transition:background .15s;
}

.co-catalog .ca-details-link:hover {
  background:#6f50b5;
}

.co-catalog .ca-details-link span { font-size:15px; }

/* PAGINATION */

.co-catalog .ca-pagination {
  display:flex;
  align-items:center;
  justify-content:space-between;
  flex-wrap:wrap;
  gap:12px;
  margin-top:16px;
  padding:12px 0;
}

.co-catalog .ca-pagination > span {
  color:#887b98;
  font-size:10px;
}

.co-catalog .ca-pagination > div {
  display:flex;
  align-items:center;
  gap:8px;
}

.co-catalog .ca-pagination button {
  padding:8px 11px;
  border:1px solid #e5dcf2;
  border-radius:8px;
  background:white;
  color:#7255ad;
  font-size:10px;
  font-weight:700;
  cursor:pointer;
}

.co-catalog .ca-pagination button:hover:not(:disabled) {
  background:#f5efff;
  border-color:#cfc0eb;
}

.co-catalog .ca-pagination button:disabled {
  opacity:.4;
  cursor:not-allowed;
}

.co-catalog .ca-pagination strong {
  min-width:42px;
  color:#665575;
  font-size:10px;
  text-align:center;
}

/* EMPTY AND LOADING STATES */

.co-catalog .ca-loading,
.co-catalog .ca-empty {
  padding:27px 15px;
  border:1px dashed #e4d8f1;
  border-radius:13px;
  background:#fcfaff;
  text-align:center;
}

.co-catalog .ca-loading {
  color:#796b8d;
  font-size:11px;
}

.co-catalog .ca-empty h3 {
  margin:0;
  color:#49385f;
  font-size:13px;
}

.co-catalog .ca-empty p {
  margin:6px 0 12px;
  color:#887b98;
  font-size:10px;
}

.co-catalog .ca-empty button {
  padding:8px 11px;
  border:1px solid #dfd2f2;
  border-radius:8px;
  background:white;
  color:#7959b8;
  font-size:10px;
  font-weight:750;
  cursor:pointer;
}

/* HELP AND FOOTER */

.co-catalog .ca-help {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:15px;
  border:1px solid #e8e0f1;
  border-radius:13px;
  background:#faf7ff;
}

.co-catalog .ca-help b {
  color:#49385f;
  font-size:11px;
}

.co-catalog .ca-help p {
  margin:4px 0 0;
  color:#887b98;
  font-size:10px;
}

.co-catalog .ca-help > a {
  flex-shrink:0;
  color:#7959b8;
  font-size:10px;
  font-weight:750;
}

.co-catalog .ca-footer {
  margin-top:26px;
  padding:17px 2px 5px;
  border-top:1px solid #e9e2f1;
}

.co-catalog .ca-footer-top {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.co-catalog .ca-footer-top b {
  color:#55416f;
  font-size:11px;
}

.co-catalog .ca-footer-top span {
  color:#988ca8;
  font-size:9px;
}

.co-catalog .ca-footer-links {
  display:flex;
  flex-wrap:wrap;
  gap:16px;
  margin-top:12px;
}

.co-catalog .ca-footer-links a {
  color:#796a8d;
  font-size:10px;
}

.co-catalog .ca-footer-links a:hover { color:#6748a8; }

.co-catalog .ca-footer-copy {
  margin-top:12px;
  color:#a399b1;
  font-size:9px;
}

/* RESPONSIVE */

@media(max-width:900px) {
  .co-catalog .ca-layout {
    grid-template-columns:175px minmax(0,1fr);
    gap:16px;
  }

  .co-catalog .ca-sidebar { padding:15px 9px; }
  .co-catalog .ca-nav { gap:8px;padding:10px 8px; }
}

@media(max-width:680px) {
  .co-catalog .ca-layout {
    grid-template-columns:1fr;
    gap:18px;
  }

  .co-catalog .ca-sidebar {
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    align-content:start;
    gap:3px;
    min-height:0;
    padding:12px;
  }

  .co-catalog .ca-brand {
    grid-column:1/-1;
    padding-bottom:12px;
  }

  .co-catalog .ca-nav-label,
  .co-catalog .ca-sidebar-bottom { display:none; }

  .co-catalog .ca-nav { margin:0; }
  .co-catalog .ca-header h1 { font-size:25px; }
  .co-catalog .ca-my-rentals { display:none; }
  .co-catalog .ca-grid { grid-template-columns:1fr; }

  .co-catalog .ca-help {
    align-items:flex-start;
    flex-direction:column;
  }

  .co-catalog .ca-footer-top {
    align-items:flex-start;
    flex-direction:column;
  }
}

sp_widget.script:
(function() {
  data.loading = true;
  data.assets = [];

  function classifyAsset(type) {
    type = (type || "").toLowerCase();

    if (type.indexOf("textbook") > -1 ||
        type.indexOf("book") > -1) {
      return "book";
    }

    if (type.indexOf("laptop") > -1 ||
        type.indexOf("computer") > -1) {
      return "laptop";
    }

    if (type.indexOf("kit") > -1 ||
        type.indexOf("equipment") > -1) {
      return "kit";
    }

    return "other";
  }

  var asset = new GlideRecord("u_campus_asset");
  asset.addQuery("u_status", "available");
  asset.orderBy("u_asset_name");
  asset.query();

  while (asset.next()) {
    data.assets.push({
      id: asset.getUniqueValue(),
      name: asset.getDisplayValue("u_asset_name") || "Campus resource",
      assetId: asset.getDisplayValue("u_asset_id") || "",
      type: asset.getDisplayValue("u_asset_type") || "",
      location: asset.getDisplayValue("u_location") || "",
      status: asset.getDisplayValue("u_status") || "Available",
      art: classifyAsset(asset.getDisplayValue("u_asset_type"))
    });
  }

  data.loading = false;
})();
